package io.knowledgebrain.collaboration;
import java.util.*;import java.io.IOException;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.MeterRegistry;
@RestController @ConditionalOnProperty(name="brain.collaboration.api.enabled",havingValue="true")
@RequestMapping("/api/groups/{groupId}/studies/{studyId}/assignments/{assignmentId}/submissions/{submissionId}/feedback/revisions/{feedbackVersion}/retraction")
final class FeedbackRetractionController {
 private final FeedbackRetractionStore store;private final StudyController gate;private final MeterRegistry metrics;
 FeedbackRetractionController(FeedbackRetractionStore store,StudyController gate,MeterRegistry metrics){this.store=store;this.gate=gate;this.metrics=metrics;}
 static String tag(long version){return "\"fr"+version+"\"";}
 static long expected(HttpServletRequest r){var values=Collections.list(r.getHeaders("If-Match"));if(values.isEmpty())throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,"Retraction If-Match required");if(values.size()!=1||!values.getFirst().matches("\"fr(0|[1-9][0-9]{0,18})\""))throw GroupInput.bad();try{return Long.parseLong(values.getFirst().substring(3,values.getFirst().length()-1));}catch(NumberFormatException e){throw GroupInput.bad();}}
 private long version(String raw){long v=gate.number(raw,0,Long.MAX_VALUE);if(v<1)throw GroupInput.bad();return v;}
 @GetMapping ResponseEntity<?> get(@PathVariable String groupId,@PathVariable String studyId,@PathVariable String assignmentId,@PathVariable String submissionId,@PathVariable String feedbackVersion,HttpServletRequest r)throws IOException{
  gate.query(r,Set.of());gate.empty(r);var group=GroupInput.id(groupId);var study=GroupInput.id(studyId);var assignment=GroupInput.id(assignmentId);var id=GroupInput.id(submissionId);long target=version(feedbackVersion);var a=gate.participant(group,r,false,gate.trace(r));var v=store.get(group,a.space(),study,assignment,id,a.actor(),a.role().equals("OWNER"),target);metrics.counter("brain.collaboration.feedback.retraction.reads","type","current").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).eTag(tag(v.retraction()==null?0:v.retraction().version())).body(v);
 }
 @PutMapping ResponseEntity<?> change(@PathVariable String groupId,@PathVariable String studyId,@PathVariable String assignmentId,@PathVariable String submissionId,@PathVariable String feedbackVersion,HttpServletRequest r)throws IOException{
  gate.query(r,Set.of());var group=GroupInput.id(groupId);var study=GroupInput.id(studyId);var assignment=GroupInput.id(assignmentId);var id=GroupInput.id(submissionId);long target=version(feedbackVersion);String trace=gate.trace(r);var a=gate.access(group,r,true,trace);long expected=expected(r);var input=FeedbackRetractionInput.parse(gate.jsonBody(r));var v=store.change(group,a.space(),study,assignment,id,a.actor(),target,expected,input,trace.substring(3,35));metrics.counter("brain.collaboration.feedback.retraction.changes","state",v.state()).increment();org.slf4j.LoggerFactory.getLogger(getClass()).info("feedback_retraction retraction_id={} state={} trace_id={}",v.retractionId(),v.state(),trace.substring(3,35));return ResponseEntity.ok().cacheControl(CacheControl.noStore()).eTag(tag(v.version())).body(v);
 }
 @GetMapping("/revisions") ResponseEntity<?> history(@PathVariable String groupId,@PathVariable String studyId,@PathVariable String assignmentId,@PathVariable String submissionId,@PathVariable String feedbackVersion,HttpServletRequest r)throws IOException{
  gate.query(r,Set.of("before","limit"));gate.empty(r);var group=GroupInput.id(groupId);var study=GroupInput.id(studyId);var assignment=GroupInput.id(assignmentId);var id=GroupInput.id(submissionId);long target=version(feedbackVersion),before=gate.number(r.getParameter("before"),Long.MAX_VALUE,Long.MAX_VALUE);int limit=(int)gate.number(r.getParameter("limit"),5,10);var a=gate.participant(group,r,false,gate.trace(r));var v=store.history(group,a.space(),study,assignment,id,a.actor(),a.role().equals("OWNER"),target,before,limit);metrics.counter("brain.collaboration.feedback.retraction.reads","type","history").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(v);
 }
}
